function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          obs.unobserve(el);
        }
      },
      { threshold: 0.15 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ children, className = "", delay = 0 }) {
  const [ref, visible] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        transition: `opacity 0.7s ease ${delay}ms, transform 0.7s cubic-bezier(.2,.8,.2,1) ${delay}ms`,
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(24px)",
      }}
    >
      {children}
    </div>
  );
}

/* Signature mark: the brain + magic wand, redrawn as inline SVG so it can
   be recolored / animated (sparkle twinkle) anywhere on the page.        */
function BrainWandMark({ className = "w-10 h-10", sparkle = true }) {
  return (
    <svg viewBox="0 0 100 100" className={className} aria-hidden="true" focusable="false">
      <circle cx="35" cy="38" r="19" fill="#B29CE8" />
      <circle cx="60" cy="32" r="18" fill="#A9DDB0" />
      <circle cx="62" cy="58" r="20" fill="#8EC9F0" />
      <circle cx="34" cy="60" r="16" fill="#9BD4EF" />
      <path d="M58 60L90 92" stroke="#C99A5B" strokeWidth="6" strokeLinecap="round" />
      <circle cx="58" cy="60" r="7.5" fill="#F3A6C6" />
      {sparkle && (
        <>
          <path
            d="M92 84l3 7 7 3-7 3-3 7-3-7-7-3 7-3z"
            fill="#FCE98B"
            className="animate-pulse"
          />
          <circle cx="102" cy="74" r="2.2" fill="#B29CE8" className="animate-pulse" />
        </>
      )}
      {!sparkle && <path d="M92 84l3 7 7 3-7 3-3 7-3-7-7-3 7-3z" fill="#FCE98B" />}
    </svg>
  );
}

function Blob({ className, fill }) {
  return (
    <div
      className={`absolute rounded-full blur-2xl opacity-60 pointer-events-none ${className}`}
      style={{ background: fill }}
    />
  );
}

